  "Abrir la versión segura": "打开安全版本",
  "La primera vez avisará de que la conexión no es privada: es el certificado propio de kywai en tu equipo. Pulsa «Configuración avanzada» → «Continuar» (en iPhone: «Mostrar detalles» → «visitar este sitio web»).": "第一次会提示连接不是私密的：这是你电脑上 kywai 自己的证书。点击「高级」→「继续前往」（iPhone 上：「显示详细信息」→「访问此网站」）。",
