  "Lo que el equipo debe recordar en este proyecto. El coordinador y los agentes lo leen en cada encargo, también después de limpiar el chat o reiniciar. Lo que dices tú queda": "团队在这个项目中需要记住的内容。协调者和代理在每次分配任务时都会读取，即使清空聊天或重启后也是如此。你说的内容是",
