  "Se llena sola: el coordinador anota lo que decides o prefieres en tus mensajes y los agentes lo que descubren («Para la memoria»). También puedes añadirlo tú o escribir «/recuerda …» en el chat.": "它会自动填充：协调者记录你在消息中做出的决定或偏好，代理记录它们发现的东西（「备忘」）。你也可以自己添加，或在聊天中输入「/remember …」。",
