  "a mano": "手动",
  "No se pudo copiar: mantén pulsada la dirección y cópiala a mano": "无法复制：请长按地址并手动复制",
  "Peticiones que se envían solas al chat de este proyecto, como si las escribieras tú: pasan por el plan, los agentes y la verificación. Se lanzan a una hora, al llegar un webhook o al cambiar archivos, mientras kywai esté abierto en el servidor. Nunca hay dos a la vez de la misma rutina. También puedes escribir": "自动发送到此项目聊天中的请求，就像你亲自输入一样：它们会经过计划、代理和验证。它们在设定时间、收到 webhook 或文件变化时运行，前提是 kywai 在服务器上处于打开状态。同一个例行任务的两次运行不会重叠。你也可以在聊天中输入",
  "/rutina cada día a las 9:00: …": "/routine every day at 9:00: …",
  "en el chat.": "。",
