  "En la demo no hay rutinas: aparecen con los agentes reales.": "演示中没有例行任务：它们会在使用真实代理时出现。",
  "Por ejemplo: cada mañana a las 8:30, «revisa las dependencias y avísame de las que tengan fallos de seguridad»; o, al llegar un PR de GitHub, «revísalo».": "例如：每天早上 8:30，「检查依赖并告诉我哪些有安全问题」；或者收到 GitHub PR 时，「审阅它」。",
