  "El acceso web está apagado: actívalo en ⚙ → Ajustes → «Acceso desde otros dispositivos…» para que este webhook reciba avisos.": "网页访问已关闭：请在 ⚙ →「从其他设备访问…」中开启，以便此 webhook 接收调用。",
  "Envía un": "发送一个",
  "a esta dirección (lleva el secreto: no la compartas). El cuerpo (por ejemplo, el evento de un PR de GitHub) se añade a la petición como datos externos, recortado. Solo llega desde tu red de Tailscale.": "到此地址（它包含密钥：不要分享）。请求体（例如 GitHub PR 事件）会被截取后作为外部数据添加到请求中。只接受来自你的 Tailscale 网络的调用。",
