  "Al guardarla tendrá su propia dirección con un secreto (botón «Webhook»). El cuerpo que llegue se añade a la petición como datos.": "保存后它会有自己带密钥的地址（「Webhook」按钮）。收到的请求体会作为数据添加到请求中。",
