  "Abrir en SomaFM": "在 SomaFM 中打开",
  "Busca una canción o un artista, o pega un enlace de YouTube. Sin anuncios: Audius (música que suben los propios artistas) y las radios de SomaFM. Las luces del espacio siguen su ritmo, sin usar el micrófono.": "搜索歌曲或艺人，或粘贴 YouTube 链接。无广告：Audius（艺人亲自上传的音乐）和 SomaFM 电台。空间的灯光会跟随节拍，无需使用麦克风。",
  "Radio de SomaFM, sin anuncios: la mantienen sus oyentes.": "SomaFM 电台，无广告：由听众支持。",
  "En Audius, de {artist}": "在 Audius 上，来自 {artist}",
  "Apoyar a SomaFM": "支持 SomaFM",
  "Busca en Audius, sin anuncios": "在 Audius 中搜索，无广告",
  "Filtra las radios (lofi, jazz, ambient…)": "筛选电台（lofi、爵士、氛围……）",
  "YouTube Music en su reproductor oficial (con sus anuncios)": "官方播放器中的 YouTube Music（含广告）",
  "Música que suben los propios artistas para escucharla gratis, sin anuncios": "艺人亲自上传、可免费收听的音乐，无广告",
  "Radios de SomaFM sin anuncios, que mantienen sus oyentes": "无广告的 SomaFM 电台，由听众支持",
  "No hay radios con ese nombre.": "没有这个名称的电台。",
  "Fuente de la música": "音乐来源",
  "Radios": "电台",
  "Con Audius y las radios, las luces escuchan el sonido directamente: no hace falta compartir nada.": "使用 Audius 和电台时，灯光直接聆听声音：无需共享任何内容。",
  "Con Audius y las radios, las luces escuchan el sonido de verdad: llega directamente a kywai, sin micrófono y sin compartir nada.": "使用 Audius 和电台时，灯光聆听真实的声音：声音直接进入 kywai，无需麦克风，也无需共享任何内容。",
  "YouTube exige que su reproductor esté a la vista: al cerrar este panel la música se pausa. Mientras suena cualquier fuente, sustituye a la música ambiental de kywai.": "YouTube 要求其播放器保持可见：关闭此面板会暂停音乐。任何来源播放时，都会替代 kywai 的环境音乐。",
  "Minimizar (sigue sonando)": "最小化（继续播放）",
  "Cerrar la música (se pausa)": "关闭音乐（会暂停）",
  "Cerrar (la música se pausa)": "关闭（音乐会暂停）",
  "Desde el navegador, YouTube no deja reproducir muchas canciones de discográficas (error 150): se busca otra subida de la misma canción. En la app de escritorio del Mac sí suenan todas.": "在浏览器中，YouTube 不允许播放很多唱片公司的歌曲（错误 150）：会搜索同一首歌的其他上传版本。在 Mac 桌面应用中都能播放。",
