  "Marca el pulso a mano o escribe el BPM: las luces lo seguirán.": "手动打拍子或输入 BPM：灯光会跟随它。",
  "La canción encontrada podría no ser esta: comprueba que las luces van a tempo o márcalo a mano.": "找到的歌曲可能不是这首：请检查灯光是否合拍，或手动打拍子。",
