  "Las luces siguen cada golpe de lo que suena (sin micrófono)": "灯光跟随正在播放内容的每一拍（不使用麦克风）",
  "Seguir el sonido real": "跟随真实声音",
  "Las luces caen en cada golpe de la canción: kywai escucha lo que suena en su propia ventana, sin micrófono y sin grabar nada.": "灯光在歌曲的每一拍闪动：kywai 收听自己窗口中播放的内容，不使用麦克风，也不录制任何东西。",
  "Apagado: las luces van con el tempo estimado (BPM publicado y desfase).": "关闭：灯光跟随估计的节奏（公开的 BPM 和偏移）。",
  "En el móvil las luces van con el tempo estimado: el navegador no puede compartir el sonido.": "在手机上灯光跟随估计的节奏：浏览器无法共享声音。",
  "Escuchando el sonido de esta pestaña: las luces caen en cada golpe.": "正在收听此标签页的声音：灯光在每一拍闪动。",
  "Dejar de escuchar": "停止收听",
  "Sincronizar con el sonido de esta pestaña": "与此标签页的声音同步",
  "El navegador te pedirá compartir esta pestaña: elígela y deja marcado «Compartir también el audio». No se graba nada.": "浏览器会要求你共享此标签页：选择它，并保持勾选「同时共享标签页音频」。不会录制任何内容。",
  "BPM puesto a mano": "手动设置的 BPM",
  "Coincidencia {c} entre el vídeo y la canción encontrada (artista, título y duración)": "视频与找到的歌曲之间的匹配度为 {c}（歌手、标题和时长）",
  "BPM a mano (40–250)": "手动 BPM（40–250）",
  "Cómo se sincronizan las luces": "灯光如何同步",
  "Es una estimación: no se escucha ni se analiza el audio (YouTube no lo permite y no se usa el micrófono). Se usa el BPM publicado de la canción (Deezer) y la posición del reproductor.": "这是估计：不会收听或分析音频（YouTube 不允许，也不使用麦克风）。它使用歌曲公开的 BPM（Deezer）和播放器的位置。",
  "Se ajusta solo al pausar, reanudar, saltar o cambiar la velocidad. El primer pulso no se conoce: si las luces van desplazadas, usa «Marcar pulso» o el desfase.": "暂停、继续、跳转或改变速度时会自动重新调整。第一拍的位置未知：如果灯光不合拍，请使用「打拍子」或偏移。",
  "Las canciones en directo, con tempo variable, remezclas o vídeos con introducción pueden desalinearse.": "现场版、节奏多变的歌曲、混音或带片头的视频可能会失去同步。",
