  "Tokens (mediana)": "Token（中位数）",
  "Lo que te sirvió, lo que pasó la verificación de otro agente a la primera o tras corregir, lo que no la superó, lo que quedó sin verificar y lo que falló. Por agente y por dificultad.": "哪些对你有用，哪些首次或修正后通过了其他代理的验证，哪些没通过，哪些未经验证，哪些失败了。按代理和难度统计。",
  "Todavía no hay tareas en este periodo. Cada tarea que haga un agente cuenta aquí en cuanto termine.": "这个时间段还没有任务。代理完成的每个任务都会立即计入这里。",
  "De las que valoraste con 👍/👎, las que te sirvieron": "在你用 👍/👎 评价过的任务中，有用的那些",
  "Le sirvió 👍": "有用 👍",
  "De las que comprobó otro agente, las que cumplían a la primera": "在其他代理验证过的任务中，首次就通过的",
  "De las que comprobó otro agente, las que tuvo que corregir": "在其他代理验证过的任务中，需要修正的",
  "De las que comprobó otro agente con fallos, las que pasaron tras corregirlas": "在验证发现问题的任务中，修正后通过的",
  "De las que comprobó otro agente, las que acabaron con fallos (relevo o «requiere intervención»)": "在其他代理验证过的任务中，最终仍有问题的（转交或「需要干预」）",
  "El verificador no dio un veredicto claro ni al pedírselo otra vez: ni aprobada ni suspendida": "即使再次要求，验证者也没有给出明确结论：既没通过也没失败",
  "No pudo hacerla, o la terminó otro agente": "没能完成，或由其他代理完成",
  "pocos datos": "数据较少",
  "Cada tarea cuenta una vez por agente, aunque tuviera varios intentos o una corrección (su tiempo y sus tokens se suman). «Le sirvió» sale de tus 👍/👎 en el chat; «verificada» y «corrección», de la comprobación por otro agente (solo las tareas que cambian archivos). Las tareas que detuviste no cuentan. «Sin dato»: tareas anteriores a que se guardara la dificultad.": "每个任务对每个代理只计一次，即使有多次尝试或修正（时间和 token 会累加）。「有用」来自你在聊天中的 👍/👎；「已验证」和「修正」来自其他代理的检查（仅限修改文件的任务）。你停止的任务不计入。「无数据」：保存难度之前的任务。",
  "El coordinador ve estas cifras en la ficha de cada agente cuando tiene": "当代理在 30 天内有",
  "tareas o más en 30 días, y las usa al repartir: la calidad pesa más que la velocidad y el coste.": "个或更多任务时，协调者会在其资料中看到这些数据，并在分配时使用：质量比速度和成本更重要。",
