  "Aún no hay medidas: se toma la cuota de Claude y GPT antes y después de cada petición.": "还没有测量数据：Claude 和 GPT 的配额会在每个请求前后读取。",
  "Se mide antes y después de cada petición, así que incluye cualquier otro uso de la misma cuenta en ese rato (por ejemplo, Claude Code en otro equipo). Una petición corta puede no llegar a mover el porcentaje.": "它在每个请求前后测量，因此包括这段时间内同一账户的其他用量（例如另一台电脑上的 Claude Code）。较短的请求可能不会改变百分比。",
