  "Para comparar con un solo agente (por ejemplo, Codex aparte), haz la misma petición allí y compárala con su fila: tiempo, tokens (en Codex, «/status») y cuota gastada.": "要与单个代理比较（例如单独使用 Codex），请在那里提出同样的请求，并与它那一行比较：时间、token（在 Codex 中为「/status」）和已用配额。",
