  "Sesión iniciada": "已登录",
  "Falta la clave de API ({label})": "缺少 API 密钥（{label}）",
  "Sin sesión": "未登录",
  "No se puede comprobar de antemano: si pide iniciar sesión, ábrelo una vez en una terminal": "无法提前检查：如果它要求登录，请在终端中打开一次",
  "Sesión iniciada: {email}": "已登录：{email}",
  "Claude Code no responde": "Claude Code 没有响应",
  "Configuración de Codex con errores (~/.codex/config.toml): {v1}": "Codex 配置有错误（~/.codex/config.toml）：{v1}",
  "Sesión iniciada con": "已登录，方式：",
