  '{name} no está disponible{why}. El mensaje no se ha pasado a ningún otro agente.': '{name} 当前不可用{why}。消息没有转给其他智能体。',
  'Ese agente ya no existe': '该智能体已不存在',
  'Hablar directamente con un agente': '直接与智能体对话',
  'Directo, sin pasar por Hermes: recibe tu texto tal cual': '直接发送，不经过 Hermes：对方原样收到你的文字',
  'Tú → {name} (directo, sin Hermes)': '你 → {name}（直接，不经过 Hermes）',
  // updater.ts
  "Hay una versión nueva de kywai ({version}).": "kywai 有新版本（{version}）。",
  "Descárgala y arrástrala a Aplicaciones para reemplazar esta. Tus proyectos y ajustes se conservan.": "下载后拖到“应用程序”中替换当前版本。你的项目和设置会保留。",
  "Descargando la versión {version}…": "正在下载 {version} 版本…",
  "Instalando la versión {version}. kywai se reabre solo.": "正在安装 {version} 版本，kywai 会自动重新打开。",
  "La versión {version} se instalará al cerrar kywai.": "{version} 版本将在关闭 kywai 时安装。",
  "comprobado en GitHub": "已在 GitHub 上检查",
  "descargándose": "正在下载",
  "se descarga de GitHub": "从 GitHub 下载",
  "ya descargada": "已下载",
  "Hay la versión {latest} (tienes la {current}). Descárgala de GitHub y arrástrala a Aplicaciones: tus proyectos y ajustes se conservan.": "已有 {latest} 版本（你的是 {current}）。从 GitHub 下载并拖到“应用程序”：你的项目和设置会保留。",
  "Hay la versión {latest} (tienes la {current}): se está descargando y kywai se reabre solo al terminar.": "已有 {latest} 版本（你的是 {current}）：正在下载，完成后 kywai 会自动重新打开。",
  "La versión {latest} ya está descargada: se instala al cerrar kywai o ahora con «Instalar y reiniciar».": "{latest} 版本已下载：关闭 kywai 时安装，或现在点击“安装并重启”。",
  "Tienes la última versión ({current}), comprobado en GitHub.": "你已是最新版本（{current}），已在 GitHub 上检查。",
  "Descargando la versión {version}: kywai se reabre solo al terminar.": "正在下载 {version} 版本：完成后 kywai 会自动重新打开。",
  "Esta versión no se actualiza desde GitHub.": "此版本不通过 GitHub 更新。",
  "No se pudo consultar GitHub": "无法查询 GitHub",
  "Versión instalada: {current}": "已安装版本：{current}",
  'El modelo no escribió nada: se le pide la respuesta': '模型什么也没写：正在请它给出回答',
  'Escribe ahora tu respuesta.': '现在请写出你的回答。',
  'El modelo no escribió ninguna respuesta; esto es lo que razonó:': '模型没有写出任何回答；以下是它的推理：',
  'El modelo local terminó sin escribir ninguna respuesta (ni texto ni razonamiento).': '本地模型结束时没有写出任何回答（既没有文字也没有推理）。',
  '{name} no escribió ninguna respuesta.': '{name} 没有写出任何回答。',
  'Razonamiento (think)': '推理（think）',
  'Encendido: piensa antes de responder (más lento, para lo que necesita mucha información).': '开启：先思考再回答（更慢，适合需要大量信息的问题）。',
  'Apagado: responde directamente, más rápido.': '关闭：直接回答，更快。',
  'Arrastra para cambiar el ancho del chat (hasta el borde: cierra ese lado) · doble clic: ancho automático': '拖动以调整聊天宽度（拖到边缘：关闭那一侧）· 双击：自动宽度',
  'Suelta para ocultar el espacio 3D (se para)': '松开以隐藏 3D 空间（将暂停）',
  'Suelta para dejar solo el espacio 3D': '松开以只显示 3D 空间',
  'Mostrar el espacio 3D (está parado mientras no se ve)': '显示 3D 空间（隐藏时处于暂停）',
  'Mostrar el espacio 3D': '显示 3D 空间',
  'Ocultar el espacio 3D (se para y el chat ocupa todo)': '隐藏 3D 空间（暂停，聊天占满窗口）',
