  // Extensiones (servidores MCP)
  "ahora mismo": "刚刚",
  "hace {n} min": "{n} 分钟前",
  "hace {n} h": "{n} 小时前",
  "hace {n} días": "{n} 天前",
  "¿Quitar «{name}»? Dejará de llegar a los agentes.": "移除“{name}”？智能体将不再获得它。",
  "Extensiones": "扩展",
  "Servidores MCP que das a los agentes. Cada tarea recibe solo los que su agente tiene encendidos.": "你提供给智能体的 MCP 服务器。每个任务只会获得其智能体已启用的服务器。",
  "Servidores MCP": "MCP 服务器",
  "Pega la línea de su README, su JSON o su dirección": "粘贴其 README 中的命令、JSON 或地址",
  "Continuar": "继续",
  "Aún no hay ninguno. Añade uno pegando la línea de instalación de su README (por ejemplo «npx -y @playwright/mcp@latest»).": "还没有。粘贴其 README 中的安装命令即可添加（例如“npx -y @playwright/mcp@latest”）。",
  "Probando… (la primera vez puede tardar: descarga el servidor)": "正在测试…（首次可能较慢：需要下载服务器）",
  "Sin probar": "未测试",
  "Llega a {name}: pulsa para quitárselo": "{name} 已获得：点击移除",
  "Dárselo a {name} (se prueba antes)": "提供给 {name}（会先测试）",
  "{name} aún no puede recibir servidores MCP de kywai": "{name} 暂时还不能接收 kywai 的 MCP 服务器",
  "Probar": "测试",
  "Al dárselo a un agente, kywai lo arranca y comprueba que responde. Si falla, se queda apagado y te dice por qué: ninguna tarea se rompe por una extensión. Hermes sabe qué herramientas tiene cada agente y reparte el trabajo con eso en cuenta.": "把它提供给智能体时，kywai 会先启动并确认它能响应。若失败，它会保持关闭并告诉你原因：任何任务都不会因扩展而出错。Hermes 知道每个智能体有哪些工具，并据此分配工作。",
  "Título (opcional)": "标题（可选）",
  "Dirección": "地址",
  "Orden que lo arranca": "启动命令",
  "Cabeceras (por ejemplo Authorization: Bearer …)": "请求头（例如 Authorization: Bearer …）",
  "Variables (claves de API, tokens…)": "变量（API 密钥、令牌…）",
  "Guardada (vacía = no cambiarla)": "已保存（留空则不修改）",
  "Valor": "值",
  "Añadir cabecera": "添加请求头",
  "Añadir variable": "添加变量",
  "Las claves se guardan cifradas en este equipo y no vuelven a mostrarse.": "密钥加密保存在这台电脑上，之后不会再显示。",
  "Guardar y probar": "保存并测试",
  "Hay un valor demasiado largo o con caracteres no permitidos": "有值过长或包含不允许的字符",
  "El nombre solo admite minúsculas, números, - y _ (empieza por una letra)": "名称只能包含小写字母、数字、- 和 _（以字母开头）",
  "Ese nombre está reservado para kywai": "该名称为 kywai 保留",
  "Ya hay un servidor con ese nombre": "已有同名服务器",
  "Hay demasiados servidores: quita alguno antes": "服务器太多：请先移除一些",
  "Falta la orden que arranca el servidor": "缺少启动服务器的命令",
  "Demasiados argumentos": "参数过多",
  "La dirección debe empezar por https:// (o ser de este equipo)": "地址必须以 https:// 开头（或位于本机）",
  "Demasiadas variables": "变量过多",
  "Demasiadas cabeceras": "请求头过多",
  "Nombre no válido: {k}": "无效名称：{k}",
  "Ese servidor ya no existe": "该服务器已不存在",
  "En Windows no se admite este argumento: {a}": "Windows 上不支持此参数：{a}",
  "Responde: 1 herramienta": "可以响应：1 个工具",
  "Responde: {n} herramientas": "可以响应：{n} 个工具",
  "Responde (sin herramientas)": "可以响应（无工具）",
  "No se pudo arrancar: {msg}": "无法启动：{msg}",
  "No respondió en {n} s": "{n} 秒内无响应",
  "No se encontró «{command}» en este equipo": "这台电脑上找不到“{command}”",
  "Se cerró al arrancar (código {code})": "启动时退出（代码 {code}）",
  "Rechazó el saludo: {msg}": "拒绝了握手：{msg}",
  "No dio sus herramientas: {msg}": "未返回工具列表：{msg}",
  "Pide autorización: añade su token como cabecera «Authorization» (Bearer …). Los que solo admiten iniciar sesión en el navegador aún no se pueden usar en las tareas": "需要授权：请把它的令牌添加为“Authorization”请求头（Bearer …）。只支持在浏览器中登录的服务器暂时无法用于任务",
  "Respondió con un error ({code})": "返回错误（{code}）",
  "No responde como un servidor MCP": "它的响应不像 MCP 服务器",
  "No dio la lista de herramientas": "未返回工具列表",
  "No se pudo conectar: {msg}": "无法连接：{msg}",
  "En Windows no se admite este valor en {k}": "Windows 上 {k} 不支持此值",
  "Las extensiones no están disponibles": "扩展不可用",
  "Sin {list}: su configuración no se puede pasar a Codex": "未使用 {list}：其配置无法传给 Codex",
  "Herramientas de Extensiones: {list}": "来自扩展的工具：{list}",
  "Ese JSON no se entiende: cópialo entero, con sus llaves": "无法读取该 JSON：请完整复制，包括花括号",
  "Falta «command» o «url» en el JSON": "JSON 中缺少“command”或“url”",
  "No hay ningún servidor en ese JSON (busca «command» o «url»)": "该 JSON 中没有服务器（查找“command”或“url”）",
  "Falta el nombre del servidor en la orden": "命令中缺少服务器名称",
  "Falta la dirección del servidor": "缺少服务器地址",
  'Cambiar el nombre de este ordenador': '重命名这台电脑',
  'Cambiar el nombre de este ordenador ({name})': '重命名这台电脑（{name}）',
