  "Cambia lo que va entre <> o {} por tu valor antes de guardar.": "保存前，请把 <> 或 {} 中的内容替换为你的值。",
  "Buscar en el registro oficial de MCP (notion, postgres, slack…)": "搜索官方 MCP 注册表（notion、postgres、slack…）",
  "Resultados del registro oficial de MCP. Cualquiera puede publicar en él: los marcados con ✓ son de empresas conocidas.": "来自官方 MCP 注册表的结果。任何人都可以发布：标有 ✓ 的来自知名公司。",
  "Destacados. Busca para ver los miles del registro oficial de MCP.": "精选。搜索可查看官方 MCP 注册表中的数千个服务器。",
