  "(no se usa: ese nombre ya lo tiene otro mod o kywai)": "（未使用：其他模组或 kywai 已使用该名称）",
  "Paneles (pestaña «Mods» junto al chat)": "面板（聊天旁的“Mods”标签）",
  "Hooks (con tu permiso)": "Hooks（已获你的许可）",
