  "sus paneles pueden conectarse a internet": "其面板可以连接互联网",
  "sus paneles pueden proponer mensajes al chat (tú confirmas)": "其面板可以向聊天提议消息（由你确认）",
  "Apagar": "关闭",
  "Los hooks de «{name}» ejecutarán estas órdenes en este equipo, en la carpeta del proyecto:\n\n{list}\n\n¿Das permiso?": "“{name}”的 hooks 将在本机的项目文件夹中运行以下命令：\n\n{list}\n\n是否允许？",
  "Quitar permiso a los hooks": "撤销 hooks 权限",
  "Permitir sus hooks": "允许其 hooks",
  "¿Quitar «{name}»?": "移除“{name}”？",
  "Los hooks ejecutan órdenes en este equipo: solo das permiso viendo cuáles son, y si una actualización del mod las cambia, hay que volver a darlo. Los paneles no pueden tocar el resto de kywai.": "Hooks 会在本机运行命令：你只有在看到具体命令后才会授权；如果模组更新改变了命令，需要重新授权。面板无法触及 kywai 的其他部分。",
  "{file} no es un JSON válido": "{file} 不是有效的 JSON",
  "El mod necesita un «name» con minúsculas, números, puntos o guiones": "模组需要一个由小写字母、数字、点或连字符组成的“name”",
  "Orden no válida: «{name}» (minúsculas, números y guiones)": "无效命令：“{name}”（小写字母、数字和连字符）",
  "La orden «/{name}» no tiene «prompt»": "命令“/{name}”没有“prompt”",
  "Hook con un «on» desconocido: «{on}» (vale {list})": "Hook 的“on”未知：“{on}”（可用：{list}）",
  "Cada hook necesita una orden «run» de una sola línea": "每个 hook 需要单行的“run”命令",
  "Panel con un «id» no válido: «{id}»": "面板的“id”无效：“{id}”",
  "El panel «{id}» apunta a un archivo .html que no está en el mod": "面板“{id}”指向的 .html 文件不在模组中",
  "El mod no declara ninguna orden, hook ni panel": "模组没有声明任何命令、hook 或面板",
