  "Lo local y los modelos «gratis» (los que acaban en :free o /free) no cuestan nada. Claude Code dice él mismo lo que costó cada tarea y se usa ese dato.": "本地运行和“免费”模型（以 :free 或 /free 结尾）不产生费用。Claude Code 会自己报告每个任务的费用，直接使用该数据。",
  "Uso y coste": "用量与费用",
  "Lo que gasta cada agente: tokens, tiempo, dinero y cuota de tus suscripciones. Para ver si compensa.": "每个智能体的消耗：token、时间、金钱和订阅额度，看看是否划算。",
  "Lo que valió a precios de API (≈: con tokens estimados)": "按 API 价格计算的价值（≈：token 为估算）",
  "Coste API": "API 费用",
  "Hermes no informa sus tokens (pasa por OmniRoute): sus llamadas cuentan, pero sus tokens no. Su coste (≈) se estima por la longitud del encargo y la respuesta, así que es un mínimo.": "Hermes 不报告 token（经由 OmniRoute）：调用次数会统计，token 不会。其费用（≈）按请求和回复的长度估算，因此是最低值。",
  "Lo dijo el propio CLI": "由 CLI 自己报告",

  // main/templates.ts (plantillas de tareas)
  "Revisar PR": "审查 PR",
  "revisar-pr": "review-pr",
  "Revisa el pull request {pr}: explica qué cambia, busca fallos, riesgos de seguridad y casos sin probar, y termina con una lista de cambios recomendados, de más a menos importante. No cambies nada del repositorio.": "审查拉取请求 {pr}：说明它改了什么，查找错误、安全风险和未测试的情况，最后按重要程度从高到低列出建议的修改。不要改动仓库中的任何内容。",
  "Resumir carpeta": "总结文件夹",
  "resumir-carpeta": "summarize-folder",
  "Lee la carpeta {slot} del proyecto y resume qué contiene: para qué sirve cada parte, cuáles son los archivos más importantes y qué parece que falta o está a medias.": "阅读项目中的文件夹 {slot}，总结其内容：每个部分的用途、最重要的文件，以及看起来缺失或未完成的部分。",
  "carpeta": "文件夹",
  "Buscar fallos": "查找错误",
  "buscar-fallos": "find-bugs",
  "Busca fallos en {slot}: errores de lógica, casos límite sin tratar y mensajes de error confusos. De cada uno di dónde está, cómo reproducirlo y cómo arreglarlo.": "在 {slot} 中查找错误：逻辑错误、未处理的边界情况和令人困惑的错误信息。对每个问题，说明它在哪里、如何复现以及如何修复。",
  "qué-revisar": "检查对象",
  "Escribir pruebas": "编写测试",
  "escribir-pruebas": "write-tests",
  "Escribe pruebas automáticas para {slot} con el sistema de pruebas que ya use el proyecto, cubre los casos normales y los límite, y ejecútalas para comprobar que pasan.": "使用项目已有的测试框架为 {slot} 编写自动化测试，覆盖正常情况和边界情况，并运行它们确认通过。",
  "qué-probar": "测试对象",
  "Actualizar dependencias": "更新依赖",
  "actualizar-dependencias": "update-deps",
  "Revisa las dependencias del proyecto: cuáles están desactualizadas o tienen fallos de seguridad conocidos. Actualiza las que sea seguro actualizar, ejecuta las pruebas y explica qué has cambiado, qué has dejado sin tocar y por qué.": "检查项目的依赖：哪些已过时或存在已知的安全漏洞。更新可以安全更新的依赖，运行测试，并说明你改了什么、哪些没动以及原因。",
  "Explicar código": "解释代码",
  "explicar-codigo": "explain-code",
  "Explica cómo funciona {slot} para alguien que no lo ha visto nunca: qué hace, cómo encaja con el resto del proyecto y qué hay que tener en cuenta al cambiarlo.": "向从未见过它的人解释 {slot} 是如何工作的：它做什么、如何与项目其他部分配合，以及修改时需要注意什么。",
  "Falta {label}": "缺少{label}",
  "{label} no es válido": "{label}无效",
  "{label} es demasiado largo (máximo {max} caracteres)": "{label}太长（最多 {max} 个字符）",
  "el nombre": "名称",
  "el texto": "文本",
  "El icono tiene que ser un emoji": "图标必须是一个表情符号",
  "La orden solo puede llevar letras sin acentos, cifras y guiones, y empezar por una letra": "命令只能包含不带重音的字母、数字和连字符，并且必须以字母开头",
  "«/{command}» ya es una orden de kywai: elige otra": "“/{command}” 已经是 kywai 的命令：请换一个",
  "Ya hay una plantilla con la orden «/{command}» ({name})": "已有使用命令 “/{command}” 的模板（{name}）",
  "Como mucho {n} plantillas": "最多 {n} 个模板",
