  "Colibri está apagado. Al encenderlo carga el modelo desde el disco, que puede tardar unos minutos.": "Colibri 已关闭。开启时会从磁盘加载模型，可能需要几分钟。",
  "No responde ningún servidor en esa dirección: enciéndelo desde su propio programa.": "该地址上没有服务器响应：请在它自己的程序中启动。",
  "Colibri no tiene ningún modelo listo. Elige uno con «./start-here.sh --reconfigure» y pulsa ⟳.": "Colibri 没有可用的模型。用「./start-here.sh --reconfigure」选择一个，然后点 ⟳。",
  "Vacía: la de la instalación de Colibri. Sirve también para otro servidor compatible con OpenAI (llama.cpp, MLX…). Colibri es lento con los modelos gigantes: en un equipo normal, mejor uno mediano como Qwen3.6-35B-A3B.": "留空：使用 Colibri 安装时的地址。也适用于其他兼容 OpenAI 的服务器（llama.cpp、MLX…）。Colibri 跑超大模型很慢：普通电脑上建议用中等模型，如 Qwen3.6-35B-A3B。",
